using System.Collections.Frozen;
using System.Reflection;
using HarmonyLib;
using MegaCrit.Sts2.Core.Entities.Creatures;
using MegaCrit.Sts2.Core.Models;

namespace CombatSolver;

// Only the audited inherited constant-true virtual body is neutral. This table
// contains metadata, never receivers, values, or combat state. A root separately
// freezes permission to use it; unknown types and overrides retain the full loop.
internal sealed class NativeHittingPermission
{
    private static readonly Guid AuditedModule = new("8a76776c-0ce1-4d4f-90bd-8cce653dad8e");
    private static readonly MethodInfo DefaultMethod = typeof(AbstractModel).GetMethod(
        nameof(AbstractModel.ShouldAllowHitting), [typeof(Creature)])!;
    private static readonly bool BodyMatches = DefaultMethod.Module.ModuleVersionId == AuditedModule
        && DefaultMethod.MetadataToken == 100669294
        && DefaultMethod.IsVirtual && DefaultMethod.ReturnType == typeof(bool)
        && DefaultMethod.GetMethodBody()?.GetILAsByteArray() is [0x17, 0x2a];
    private static readonly Lazy<FrozenSet<Type>> DefaultTypes = new(BuildDefaultTypes);

    private readonly FrozenSet<Type>? _types;

    private NativeHittingPermission(FrozenSet<Type>? types) => _types = types;

    internal bool Enabled => _types is not null;

    internal bool IsNeutral(Type type) => _types?.Contains(type) == true;

    internal static NativeHittingPermission Capture()
        => new(BodyMatches && Harmony.GetPatchInfo(DefaultMethod) is not { Owners.Count: > 0 }
            ? DefaultTypes.Value : null);

    private static FrozenSet<Type> BuildDefaultTypes()
    {
        if (!BodyMatches) return FrozenSet<Type>.Empty;
        List<Type> types = [];
        foreach (Type type in typeof(AbstractModel).Assembly.GetTypes())
        {
            if (type.IsAbstract || type.ContainsGenericParameters
                || !typeof(AbstractModel).IsAssignableFrom(type))
                continue;
            MethodInfo? implementation = type.GetMethod(nameof(AbstractModel.ShouldAllowHitting),
                BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic,
                binder: null, types: [typeof(Creature)], modifiers: null);
            if (implementation?.DeclaringType != typeof(AbstractModel)
                || implementation.Module != DefaultMethod.Module
                || implementation.MetadataToken != DefaultMethod.MetadataToken)
                continue;
            // Inspect virtual slots too, conservatively rejecting a nonpublic or
            // renamed override rather than inferring dispatch only from its name.
            bool hasOverride = type.GetMethods(BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)
                .Any(method => method.IsVirtual && method.DeclaringType != typeof(AbstractModel)
                    && method.GetBaseDefinition().Module == DefaultMethod.Module
                    && method.GetBaseDefinition().MetadataToken == DefaultMethod.MetadataToken);
            if (!hasOverride) types.Add(type);
        }
        return types.ToFrozenSet();
    }
}

