using System.Collections.Concurrent;
using System.Reflection;
using System.Runtime.CompilerServices;
using System.Text.Json;
using HarmonyLib;
using MegaCrit.Sts2.Core.Entities.Creatures;
using MegaCrit.Sts2.Core.Models;
using MegaCrit.Sts2.Core.Models.Powers;

namespace CombatSolver;

internal static class HittableCallbackProbe
{
    private static readonly Guid NativeModule = new("8a76776c-0ce1-4d4f-90bd-8cce653dad8e");
    private static readonly ConditionalWeakTable<IReadOnlyList<AbstractModel>, SourceData> Sources = new();
    private static readonly ConcurrentDictionary<Type, bool> Types = new();
    private static readonly ThreadLocal<Counts> Cells = new(() => new(), trackAllValues: true);
    private static readonly MethodInfo DefaultMethod = typeof(AbstractModel).GetMethod(
        nameof(AbstractModel.ShouldAllowHitting), [typeof(Creature)])!;
    private static readonly bool BaseBodyMatches = DefaultMethod.Module.ModuleVersionId == NativeModule
        && DefaultMethod.MetadataToken == 100669294
        && DefaultMethod.GetMethodBody()?.GetILAsByteArray() is [0x17, 0x2a];
    private static readonly bool BasePatched = Harmony.GetPatchInfo(DefaultMethod) is { } patches
        && patches.Owners.Count != 0;

    private sealed class SourceData(int count, int defaults, int ignored, int unknown)
    {
        internal readonly int Count = count;
        internal readonly int Defaults = defaults;
        internal readonly int Ignored = ignored;
        internal readonly int Unknown = unknown;
        internal long Calls;
    }
    private sealed class Counts
    {
        internal long Calls, Elements, Defaults, Ignored, Unknown, AllDefaultCalls, FirstVisits;
        internal readonly long[] LengthBands = new long[8];
    }

    static HittableCallbackProbe()
    {
        AppDomain.CurrentDomain.ProcessExit += (_, _) => Write();
    }

    internal static void Observe(IReadOnlyList<AbstractModel> source)
    {
        SourceData data = Sources.GetValue(source, static items =>
        {
            int defaults=0, ignored=0, unknown=0;
            for (int i=0; i<items.Count; i++)
            {
                AbstractModel item=items[i];
                if (item is ReattachPower or IllusionPower or AdaptablePower or DieForYouPower) ignored++;
                else if (Types.GetOrAdd(item.GetType(), static type =>
                {
                    MethodInfo? method=type.GetMethod(nameof(AbstractModel.ShouldAllowHitting), [typeof(Creature)]);
                    return BaseBodyMatches && !BasePatched && type.Module.ModuleVersionId==NativeModule
                        && method?.DeclaringType==typeof(AbstractModel)
                        && method.MetadataToken==DefaultMethod.MetadataToken;
                })) defaults++;
                else unknown++;
            }
            return new(items.Count, defaults, ignored, unknown);
        });
        Counts cell=Cells.Value!;
        cell.Calls++; cell.Elements+=data.Count; cell.Defaults+=data.Defaults;
        cell.Ignored+=data.Ignored; cell.Unknown+=data.Unknown;
        if(data.Unknown==0) cell.AllDefaultCalls++;
        if(Interlocked.Increment(ref data.Calls)==1) cell.FirstVisits++;
        int band=data.Count==0?0:data.Count<=16?1:data.Count<=32?2:data.Count<=64?3:
            data.Count<=128?4:data.Count<=256?5:data.Count<=1024?6:7;
        cell.LengthBands[band]++;
    }

    private static void Write()
    {
        string? output=Environment.GetEnvironmentVariable("HITTABLE_CALLBACK_PROBE_OUTPUT");
        if (string.IsNullOrEmpty(output)) return;
        Counts total=new();
        foreach(Counts c in Cells.Values)
        {
            total.Calls+=c.Calls;total.Elements+=c.Elements;total.Defaults+=c.Defaults;
            total.Ignored+=c.Ignored;total.Unknown+=c.Unknown;total.AllDefaultCalls+=c.AllDefaultCalls;
            total.FirstVisits+=c.FirstVisits;
            for(int i=0;i<8;i++)total.LengthBands[i]+=c.LengthBands[i];
        }
        var result=new { scope="observational: original death gate and all callbacks retained; per-source classification covers full source, not actual short-circuited invocation counts",
            baseBodyMatches=BaseBodyMatches, basePatched=BasePatched, calls=total.Calls,
            sourceElements=total.Elements, defaultSourceElements=total.Defaults,
            ignoredSourceElements=total.Ignored, unknownSourceElements=total.Unknown,
            allDefaultSourceCalls=total.AllDefaultCalls, distinctObservedSources=total.FirstVisits,
            callsPerSource=(double)total.Calls/Math.Max(1,total.FirstVisits),
            meanSourceLength=(double)total.Elements/Math.Max(1,total.Calls),
            allDefaultCallsFraction=(double)total.AllDefaultCalls/Math.Max(1,total.Calls),
            bands=new[]{"0","1..16","17..32","33..64","65..128","129..256","257..1024",">1024"},
            callsByLengthBand=total.LengthBands, counterThreads=Cells.Values.Count,
            types=Types.Select(kv=>new{type=kv.Key.FullName,module=kv.Key.Module.ModuleVersionId,knownDefault=kv.Value}).OrderBy(x=>x.type).ToArray() };
        File.WriteAllText(output,JsonSerializer.Serialize(result,new JsonSerializerOptions{WriteIndented=true}));
    }
}

