using CombatSolver.Engine.Common;
using CombatSolver.Engine.InCombat.Simulation;

namespace CombatSolver;

internal sealed partial class UnattendedTestRunner
{
    private void AssertHittingPermissionContract(CombatState live, Player player)
    {
        using IDisposable isolation = SimulationNotificationIsolation.Enter();
        string liveBefore=ContinuationStamp.CaptureLive(live).StateText;
        CombatRootSnapshot root=CombatRootSnapshot.Capture(live);
        CombatPredictionSimulator parent=root.ForkSimulator();
        SimulatedCombatState combat=(SimulatedCombatState)parent.State.CombatState;
        Creature target=root.Enemies[0];
        var semantics=(ICombatPredictionCreatureSemantics)combat;
        FieldInfo flag=typeof(SimulatedCombatState).GetField("_hittingListenerCertificate",BindingFlags.Instance|BindingFlags.NonPublic)!;
        FieldInfo source=typeof(SimulatedCombatState).GetField("_effectiveHookListeners",BindingFlags.Instance|BindingFlags.NonPublic)!;
        MethodInfo invalidate=typeof(SimulatedCombatState).GetMethod("InvalidateHookListeners",BindingFlags.Instance|BindingFlags.NonPublic)!;
        int checks=0;
        void Check(bool result,string message){if(!result)throw new InvalidOperationException(message);checks++;}
        NativeHittingPermission permission=NativeHittingPermission.Capture();
        Check(permission.Enabled,"Native hitting permission unexpectedly rejected root.");
        MethodInfo defaultMethod=typeof(AbstractModel).GetMethod(nameof(AbstractModel.ShouldAllowHitting),[typeof(Creature)])!;
        int nativeDefaults=0, nativeOverrides=0;
        foreach(AbstractModel model in ModelDb.All)
        {
            if(!permission.IsNeutral(model.GetType()))
            {
                MethodInfo? overridden=model.GetType().GetMethod(nameof(AbstractModel.ShouldAllowHitting),[typeof(Creature)]);
                if(overridden?.DeclaringType!=typeof(AbstractModel))nativeOverrides++;
                continue;
            }
            MethodInfo actual=model.GetType().GetMethod(nameof(AbstractModel.ShouldAllowHitting),[typeof(Creature)])!;
            Check(actual.DeclaringType==typeof(AbstractModel)&&actual.MetadataToken==defaultMethod.MetadataToken
                &&model.ShouldAllowHitting(target),"Certified native type did not execute the exact default true body.");
            nativeDefaults++;
        }
        Check(nativeDefaults>500,"Native default checks did not cover the stock model set.");
        Check(!permission.IsNeutral(typeof(NoOverrideSubscriber))&&!permission.IsNeutral(typeof(HittingContractObserver)),
            "Unknown source received native default permission.");
        combat.SetAmount<StrengthPower>(player.Creature,2);
        Check(semantics.IsHittable(target)&&(byte)flag.GetValue(combat)! ==1,"Default source was not certified.");
        object originalSource=source.GetValue(combat)!;
        Check(semantics.IsHittable(target)&&ReferenceEquals(originalSource,source.GetValue(combat)),"Warm query changed source.");
        string parentBefore=DescribeContinuationContractState(parent,root,player);
        CombatPredictionSimulator child=parent.Fork();
        SimulatedCombatState childCombat=(SimulatedCombatState)child.State.CombatState;
