using System.Diagnostics;
using System.Runtime.CompilerServices;
using System.Text.Json;

namespace CombatSolver.Engine.Common;

// Diagnostic shadow tables contain the immutable layout already verified by the
// production caller. No receiver, source list, simulator or branch value is held.
internal static class HookLayoutCapacityProbe
{
    private static readonly ConditionalWeakTable<MirroredHookListenerFilter, Probe> Roots = new();
    private static readonly List<Probe> Captured = [];
    private static readonly int[] Capacities = [2048,4096,8192,16384,32768];
    private sealed class Probe
    {
        internal readonly object Gate = new();
        internal readonly MirroredHookListenerLayout?[][] Tables = Capacities.Select(n=>new MirroredHookListenerLayout?[n]).ToArray();
        internal readonly long[] Hits = new long[Capacities.Length];
        internal readonly long[] Misses = new long[Capacities.Length];
        internal readonly long[] Collisions = new long[Capacities.Length];
        internal long Calls, Elements, ElapsedTicks;
        internal int MaximumLength;
    }

    static HookLayoutCapacityProbe() => AppDomain.CurrentDomain.ProcessExit += (_,_)=>Write();

    internal static void Observe(MirroredHookListenerFilter root, uint hash, MirroredHookListenerLayout layout)
    {
        long start=Stopwatch.GetTimestamp();
        Probe p=Roots.GetValue(root,static _=>
        {
            Probe result=new(); lock(Captured) Captured.Add(result); return result;
        });
        lock(p.Gate)
        {
            p.Calls++;p.Elements+=layout.Entries.Length;p.MaximumLength=Math.Max(p.MaximumLength,layout.Entries.Length);
            for(int c=0;c<Capacities.Length;c++)
            {
                int slot=(int)(hash&(uint)(Capacities[c]-1));
                MirroredHookListenerLayout? previous=p.Tables[c][slot];
                if(previous is not null && SameTypes(previous,layout))p.Hits[c]++;
                else
                {
                    p.Misses[c]++;if(previous is not null)p.Collisions[c]++;
                    p.Tables[c][slot]=layout;
                }
            }
            p.ElapsedTicks+=Stopwatch.GetTimestamp()-start;
        }
    }

    private static bool SameTypes(MirroredHookListenerLayout a,MirroredHookListenerLayout b)
    {
        if(ReferenceEquals(a,b))return true;
        if(a.Entries.Length!=b.Entries.Length)return false;
        for(int i=0;i<a.Entries.Length;i++)if(a.Entries[i].Type!=b.Entries[i].Type)return false;
        return true;
    }

    private static void Write()
    {
        string? path=Environment.GetEnvironmentVariable("HOOK_LAYOUT_CAPACITY_PROBE_OUTPUT");
        if(string.IsNullOrWhiteSpace(path))return;
        object[] rows;
        lock(Captured) rows=Captured.Select(p=>
        {
            lock(p.Gate) return (object)new
            {
                calls=p.Calls,elements=p.Elements,maximumLength=p.MaximumLength,
                observerElapsedSeconds=(double)p.ElapsedTicks/Stopwatch.Frequency,
                tables=Capacities.Select((capacity,c)=>new
                {
                    capacity,hits=p.Hits[c],misses=p.Misses[c],collisions=p.Collisions[c],
                    hitFraction=p.Calls==0?0:(double)p.Hits[c]/p.Calls,
                    occupiedSlots=p.Tables[c].Count(x=>x is not null),
                    estimatedRetainedPayloadBytes=(long)capacity*IntPtr.Size+p.Tables[c].Where(x=>x is not null)
                        .Sum(x=>56L+16L*x!.Entries.Length),
                }).ToArray()
            };
        }).ToArray();
        File.WriteAllText(path,JsonSerializer.Serialize(new
        {
            scope="diagnostic: lock-serialized observer arrival order; original concurrent cache untouched; layout types/masks only; per-table estimated payload includes pointer array/layout/Entry[] and can double-count layouts shared across tables",
            rows
        },new JsonSerializerOptions{WriteIndented=true}));
    }
}

